window.PoeticsWorld=function(city){if(city!=='Ogbomoso')return `<div class="unmapped-city"><h3>${city}</h3><p>This city’s visual district is still awaiting local map research. The travel simulation remains available below.</p><p class="caption">The LAUTECH-area adaptation is specific to Ogbomoso.</p></div>`;return `<div class="city-world regional-world"><canvas id="city-canvas" tabindex="0" aria-label="Fictional compressed LAUTECH-area neighbourhood. Arrow keys or W A S D to move; drag to rotate."></canvas><svg viewBox="0 0 1000 570" role="img" aria-label="Compressed campus-district diagram; positions and distances are adapted for play"><rect width="1000" height="570" fill="#d6d0b8"/><path d="M760 0V570M120 210H760M370 210V540" stroke="#8b8c80" stroke-width="35"/><path d="M760 0V570" stroke="#eee8d4" stroke-width="2" stroke-dasharray="15 12"/><rect x="120" y="50" width="420" height="120" fill="#eee6d3"/><rect x="120" y="50" width="110" height="120" fill="#335ca2"/><circle cx="490" cy="110" r="35" fill="#bb3f36"/><rect x="80" y="380" width="160" height="100" fill="#c7b594"/><rect x="430" y="340" width="180" height="90" fill="#d9ac36"/><rect x="820" y="350" width="130" height="100" fill="#c7b594"/><text x="275" y="115" fill="#333b36" font-family="Arial" font-size="24">LadoTech</text><text x="785" y="270" transform="rotate(90 785 270)" fill="#383e37" font-family="Arial" font-size="15">Old road / compressed</text><text x="90" y="440" fill="#333b36" font-family="Arial" font-size="18">Under-Verse</text><text x="445" y="390" fill="#333b36" font-family="Arial" font-size="18">Lion’s Lines</text></svg><div class="city-name">Ogbomoso <span>LAUTECH-area adaptation / fictional venues</span></div><button class="gta-minimap" data-open-map aria-label="Open full district map">${window.PoeticsMap.render()}<span>MAP / M</span></button><div class="district-key"><i class="key-red"></i><i class="key-blue"></i><i class="key-yellow"></i></div></div><div class="world-control-bar"><div class="walk-pad" aria-label="Movement controls"><button data-walk="w" aria-label="Walk forward">W</button><button data-walk="a" aria-label="Walk left">A</button><button data-walk="s" aria-label="Walk backward">S</button><button data-walk="d" aria-label="Walk right">D</button></div><span id="world-help" class="caption">Arrows / WASD to walk · Drag to look</span><div class="zoom-controls"><button data-zoom="-3" aria-label="Zoom in">+</button><button data-zoom="3" aria-label="Zoom out">−</button></div></div><div class="neighbourhood-picker" aria-label="Choose neighbourhood"><span>Neighbourhoods</span><div><button data-place="underg">Under-G</button><button data-place="gate">LAUTECH Gate</button><button data-place="adenike">Adenike</button><button data-place="general">General</button></div></div><div class="world-places"><button data-open-map>Map · M</button><button data-place="home">Under-Verse Court</button><button data-place="studio">LadoTech Studio</button><button data-place="stage">Lion’s Lines</button><button data-place="work">VerseMart</button><button data-phone>Phone</button></div><p id="place-status" class="caption" role="status">A compressed game district, not a survey or a reconstruction of 2010.</p><details class="district-method"><summary>Real places & map references</summary><p class="caption">LadoTech draws on the university campus; Under-Verse on the Under-G area; Lion’s Lines on the documented Lion’s Lounge venue. VerseMart is invented. The real campus has a first gate on Old Ogbomoso–Ilorin Road and a second gate at Under-G. Adenike and General are included as named local areas. Positions, connecting roads, distances and buildings here remain adapted for play, not measured geography.</p><a class="btn" href="https://www.openstreetmap.org/#map=16/8.16676/4.26804" target="_blank" rel="noopener">OpenStreetMap </a> <a class="btn" href="https://lautech.edu.ng/de/node/115" target="_blank" rel="noopener">University source </a><p class="caption">Google Maps could not be inspected: web retrieval returned JavaScript-only content and the interactive browser reported ERR_BLOCKED_BY_CLIENT. Exact street-layout validation remains pending.</p></details>`;};
